import components from './index'

export default {
  name: 'useComponent',
  mixins: [components],
  props: {
    //表单规则
    rules: {
      type: Array,
      default() {
        return []
      },
    },
    //表单验证
    validate: {
      type: Object,
      default() {
        return {}
      },
    },
    //全部错误
    errorsValidate: {
      type: Array,
      default() {
        return []
      },
    },
  },
  created() {
  },
  methods: {
    changeValue(e) {
      this.$emit('changeValue', { field: e.field, value: e.value })
    },
  },
}
